<script setup>import {computed,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ShoppingBag,ChevronLeft,MapPin} from 'lucide-vue-next';import {useProductStore} from '../stores/productStore';import {useCartStore} from '../stores/cartStore';import {useFloorStore} from '../stores/floorStore';import ProductGallery from '../components/product/ProductGallery.vue';import QuickAdd from '../components/product/QuickAdd.vue';const route=useRoute(),router=useRouter(),s=useProductStore(),floor=useFloorStore();const p=computed(()=>s.bySlug(route.params.slug));</script><template><main v-if="p" class="detail-page"><button class="back" @click="router.back()"><ChevronLeft/> Quay lại</button><ProductGallery :product="p"/><section class="detail-copy"><span class="kicker">{{p.categoryName}}</span><h1>{{p.name}}</h1><div class="detail-rating">★★★★★ <span>{{p.rating}} · Đã bán {{p.sold}}</span></div><p>{{p.description}}</p><div class="stock"><span><MapPin/> Tầng 14: còn {{p.stock[14]}}</span><span><MapPin/> Tầng 20: còn {{p.stock[20]}}</span></div><strong class="detail-price">{{p.price.toLocaleString('vi-VN')}} ₫</strong><div class="buy-row"><QuickAdd :product="p" :stock="p.stock[floor.floor]" /></div><small>Đang chọn điểm nhận: tầng {{floor.floor}}</small></section></main><main v-else class="page"><h1>Không tìm thấy sản phẩm</h1><RouterLink to="/products">Quay lại danh sách</RouterLink></main></template>
